'use strict';
window.HomepageEditor={pending:0,render(catalogue,onChange,api){
 const root=document.getElementById('homepage-fields');root.replaceChildren();document.getElementById('homepage-form').onsubmit=e=>e.preventDefault();
 catalogue.homepage=Catalogue.home(catalogue);const h=catalogue.homepage;
 const text=(parent,label,value,change,multiline=false,max=2000)=>{const wrap=document.createElement('label'),input=document.createElement(multiline?'textarea':'input');wrap.textContent=label;input.value=value;input.maxLength=max;input.required=true;if(multiline)input.rows=3;input.oninput=()=>{change(input.value);onChange();};wrap.append(input);parent.append(wrap);return input;};
 const group=title=>{const section=document.createElement('section'),heading=document.createElement('h3');heading.textContent=title;section.className='homepage-group';section.append(heading);root.append(section);return section;};
 const photo=(parent,src,alt,change)=>{const box=document.createElement('div'),img=document.createElement('img'),label=document.createElement('label'),file=document.createElement('input'),note=document.createElement('p');img.src=src;img.alt=alt;img.className='homepage-preview';label.textContent='Upload replacement photo';file.type='file';file.accept='image/jpeg,image/png,image/webp';label.append(file);note.className='helper';note.textContent='JPG, PNG or WebP, up to 2 MB. Photos publish when you save.';box.append(img,label,note);parent.append(box);file.onchange=async()=>{const selected=file.files[0];if(!selected)return;this.pending++;onChange();file.disabled=true;try{if(selected.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(selected.type))throw Error('Choose a JPG, PNG or WebP under 2 MB.');note.textContent='Uploading…';const body=new FormData();body.append('image',selected);const result=await api('upload',{method:'POST',body});change(result.url);img.src=result.url;note.textContent='Uploaded. Save changes to publish.';onChange();}catch(e){note.textContent=e.message;}finally{this.pending--;file.disabled=false;file.value='';}};};
 const fields=(parent,keys)=>keys.forEach(([key,label,multiline])=>text(parent,label,h[key],v=>h[key]=v,multiline));
 const hero=group('Main banner');fields(hero,[['announcement','Announcement'],['heroEyebrow','Banner label'],['heroTitle','Main headline',true],['heroDescription','Banner description',true],['heroButton','Button text'],['heroAlt','Photo description']]);photo(hero,h.heroImage,h.heroAlt,v=>h.heroImage=v);
 const story=group('Brand story');fields(story,[['storyTitle','Story headline',true],['storyText','Story text',true],['storyAlt','Photo description']]);photo(story,h.storyImage,h.storyAlt,v=>h.storyImage=v);
 const collection=group('Collection and new arrivals');fields(collection,[['collectionTitle','Collection headline',true],['collectionDescription','Collection description',true]]);const help=document.createElement('p');help.className='helper';help.textContent='Select and order products to feature. Leave all unchecked to display the full collection. Other products remain available under “All pieces”.';collection.append(help);const choices=document.createElement('div');collection.append(choices);
 const drawChoices=()=>{choices.replaceChildren();const ordered=[...h.featuredIds.map(id=>catalogue.products.find(p=>p.id===id)).filter(Boolean),...catalogue.products.filter(p=>!h.featuredIds.includes(p.id))];ordered.forEach(p=>{const row=document.createElement('div'),label=document.createElement('label'),check=document.createElement('input');row.className='featured-row';check.type='checkbox';check.checked=h.featuredIds.includes(p.id);check.onchange=()=>{h.featuredIds=check.checked?[...h.featuredIds,p.id]:h.featuredIds.filter(id=>id!==p.id);onChange();drawChoices();};label.append(check,document.createTextNode(p.name));row.append(label);if(check.checked){for(const [name,delta]of [['↑',-1],['↓',1]]){const b=document.createElement('button');b.type='button';b.textContent=name;b.setAttribute('aria-label',(delta<0?'Move up ':'Move down ')+p.name);const i=h.featuredIds.indexOf(p.id);b.disabled=i+delta<0||i+delta>=h.featuredIds.length;b.onclick=()=>{[h.featuredIds[i],h.featuredIds[i+delta]]=[h.featuredIds[i+delta],h.featuredIds[i]];onChange();drawChoices();};row.append(b);}}choices.append(row);});};drawChoices();
 const campaign=group('Photoshoot gallery');fields(campaign,[['campaignTitle','Gallery headline',true],['campaignDescription','Gallery introduction',true]]);const helpGallery=document.createElement('p');helpGallery.className='helper';helpGallery.textContent='Up to 12 photos. Remove all photos to hide this section.';campaign.append(helpGallery);const list=document.createElement('div');campaign.append(list);
 const drawGallery=()=>{list.replaceChildren();h.gallery.forEach((p,i)=>{const card=document.createElement('div');card.className='homepage-gallery-card';photo(card,p.image,p.alt,v=>p.image=v);text(card,'Caption',p.caption,v=>p.caption=v,false,150).required=false;text(card,'Photo description',p.alt,v=>p.alt=v,false,250);for(const [label,delta]of [['Move up',-1],['Move down',1]]){const b=document.createElement('button');b.type='button';b.className='underlink';b.textContent=label;b.disabled=i+delta<0||i+delta>=h.gallery.length;b.onclick=()=>{if(this.pending)return;[h.gallery[i],h.gallery[i+delta]]=[h.gallery[i+delta],h.gallery[i]];onChange();drawGallery();};card.append(b);}const remove=document.createElement('button');remove.type='button';remove.textContent='Remove photo';remove.className='underlink danger';remove.onclick=()=>{if(this.pending)return;h.gallery.splice(i,1);onChange();drawGallery();};card.append(remove);list.append(card);});add.disabled=h.gallery.length>=12;};
 const add=document.createElement('button'),picker=document.createElement('input');add.type='button';add.className='underlink';add.textContent='Add gallery photo +';picker.type='file';picker.accept='image/jpeg,image/png,image/webp';picker.hidden=true;add.onclick=()=>{if(!this.pending&&h.gallery.length<12)picker.click();};picker.onchange=async()=>{const file=picker.files[0];if(!file)return;this.pending++;add.disabled=true;try{if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP under 2 MB.');helpGallery.textContent='Uploading new gallery photo…';const body=new FormData();body.append('image',file);const result=await api('upload',{method:'POST',body});h.gallery.push({image:result.url,caption:'NEW ARRIVAL',alt:'New arrival photoshoot'});onChange();drawGallery();helpGallery.textContent='Photo added. Edit its caption and description, then save changes to publish.';}catch(e){helpGallery.textContent=e.message;}finally{this.pending--;picker.value='';add.disabled=h.gallery.length>=12;}};campaign.append(add,picker);drawGallery();
 },valid(){if(this.pending)throw Error('Please wait for photo uploads to finish before saving.');return document.getElementById('homepage-form').reportValidity();}};
